import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';

const Dashboard = ({ setAuth }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [products, setProducts] = useState([]);
  const [cart, setCart] = useState([]);
  const [showCart, setShowCart] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchCategory, setSearchCategory] = useState('All');
  const [sortBy, setSortBy] = useState('newest');
  const [showFilters, setShowFilters] = useState(false);
  const [productsError, setProductsError] = useState('');
  const navigate = useNavigate();

  // Get unique categories from products
  const categories = ['All', ...new Set(products.map(p => p.category))];

  useEffect(() => {
    const fetchDashboardData = async () => {
      try {
        // Try to fetch user profile (optional - use mock user if fails)
        try {
          const res = await axios.get('/api/auth/me');
          setUser(res.data);
        } catch (profileErr) {
          // Use mock user if API fails
          const mockUser = {
            username: localStorage.getItem('username') || 'User',
            email: localStorage.getItem('email') || 'user@example.com',
            createdAt: new Date().toISOString()
          };
          setUser(mockUser);
        }

        // Fetch products from backend API
        try {
          console.log('📦 Fetching products from API...');
          const productsRes = await axios.get('http://localhost:5000/api/products');
          if (productsRes.data.success) {
            console.log(`✅ Fetched ${productsRes.data.products.length} products`);
            setProducts(productsRes.data.products);
            setProductsError('');
          } else {
            console.warn('⚠️ Products API returned unsuccessful status');
            setProductsError('Failed to fetch products');
          }
        } catch (productsErr) {
          console.error('❌ Error fetching products:', productsErr.message);
          setProductsError('Failed to load products. Please try refreshing the page.');
          setProducts([]);
        }

        // Load cart from localStorage
        const savedCart = JSON.parse(localStorage.getItem('cart')) || [];
        setCart(savedCart);
      } catch (err) {
        console.error('Error:', err);
        localStorage.removeItem('token');
        setAuth(false);
        navigate('/login');
      } finally {
        setLoading(false);
      }
    };

    fetchDashboardData();
  }, [setAuth, navigate]);

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    localStorage.removeItem('email');
    localStorage.removeItem('username');
    setAuth(false);
    navigate('/login');
  };

  const handleAddToCart = (product) => {
    const productId = product._id || product.id;
    const existingItem = cart.find(item => (item._id || item.id) === productId);
    let updatedCart;

    if (existingItem) {
      updatedCart = cart.map(item =>
        (item._id || item.id) === productId ? { ...item, quantity: item.quantity + 1 } : item
      );
    } else {
      updatedCart = [...cart, { ...product, quantity: 1 }];
    }

    setCart(updatedCart);
    localStorage.setItem('cart', JSON.stringify(updatedCart));
  };

  const handleRemoveFromCart = (productId) => {
    const updatedCart = cart.filter(item => (item._id || item.id) !== productId);
    setCart(updatedCart);
    localStorage.setItem('cart', JSON.stringify(updatedCart));
  };

  const handleClearCart = () => {
    setCart([]);
    localStorage.removeItem('cart');
  };

  const filteredProducts = products.filter(product =>
    product.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
    product.category.toLowerCase().includes(searchQuery.toLowerCase()) ||
    product.description.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const cartTotal = cart.reduce((total, item) => total + (parseFloat(item.price) * item.quantity), 0);

  if (loading) {
    return (
      <div className="dashboard-container">
        <div className="loading-spinner">
          <p>⏳ Loading dashboard...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="dashboard-container">
      {/* User Welcome Section */}
      <div className="user-section">
        <div className="user-info">
          <h1>Welcome, {user?.username}! 👋</h1>
          <p className="user-email">Email: {user?.email}</p>
          <p className="user-since">Member since: {user?.createdAt ? new Date(user.createdAt).toLocaleDateString() : 'Today'}</p>
        </div>
        <button onClick={handleLogout} className="btn btn-danger">
          🚪 Logout
        </button>
      </div>

      {/* Cart Section */}
      <div className="cart-section">
        <button 
          className="cart-toggle-btn"
          onClick={() => setShowCart(!showCart)}
        >
          🛒 Cart ({cart.length})
        </button>

        {showCart && (
          <div className="cart-panel">
            <h3>Shopping Cart</h3>
            {cart.length === 0 ? (
              <p className="empty-cart">Your cart is empty</p>
            ) : (
              <>
                <div className="cart-items">
                  {cart.map(item => (
                    <div key={item._id || item.id} className="cart-item">
                      <div className="cart-item-info">
                        <img 
                          src={item.imageUrl} 
                          alt={item.title || item.name}
                          className="cart-item-image"
                          onError={(e) => {e.target.src = 'https://via.placeholder.com/40?text=Product'}}
                        />
                        <div>
                          <p className="cart-item-name">{item.title || item.name}</p>
                          <p className="cart-item-price">Qty: {item.quantity} × ${parseFloat(item.price).toFixed(2)}</p>
                        </div>
                      </div>
                      <p className="cart-item-total">${(parseFloat(item.price) * item.quantity).toFixed(2)}</p>
                      <button 
                        className="btn-remove"
                        onClick={() => handleRemoveFromCart(item._id || item.id)}
                      >
                        ✕
                      </button>
                    </div>
                  ))}
                </div>
                <div className="cart-footer">
                  <div className="cart-total">
                    <strong>Total:</strong>
                    <strong>${cartTotal.toFixed(2)}</strong>
                  </div>
                  <button className="btn btn-primary">Checkout</button>
                  <button 
                    className="btn btn-secondary"
                    onClick={handleClearCart}
                  >
                    Clear Cart
                  </button>
                </div>
              </>
            )}
          </div>
        )}
      </div>

      {/* Products Section */}
      <div className="products-section">
        <div className="products-header">
          <h2>🛍️ Featured Products</h2>
          <div className="search-box">
            <input
              type="text"
              placeholder="Search products..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="search-input"
            />
          </div>
        </div>

        {productsError && (
          <div className="alert alert-error">
            <p>⚠️ {productsError}</p>
          </div>
        )}

        {products.length === 0 && !productsError ? (
          <div className="no-products">
            <p>📦 No products available yet</p>
            <p style={{fontSize: '0.9rem', color: '#999', marginTop: '10px'}}>Add some products to get started!</p>
          </div>
        ) : filteredProducts.length === 0 ? (
          <div className="no-products">
            <p>🔍 No products found matching your search</p>
          </div>
        ) : (
          <div className="products-grid">
            {filteredProducts.map(product => (
              <div key={product._id || product.id} className="product-card">
                <div className="product-image">
                  <img 
                    src={product.imageUrl} 
                    alt={product.title}
                    onError={(e) => {e.target.src = 'https://via.placeholder.com/300?text=Product'}}
                  />
                </div>
                <div className="product-details">
                  <h3>{product.title}</h3>
                  <p className="product-category">📁 {product.category}</p>
                  <p className="product-description">{product.description}</p>
                  {product.stock !== undefined && (
                    <p className="product-stock">
                      📊 Stock: <span className={product.stock > 0 ? 'in-stock' : 'out-of-stock'}>{product.stock > 0 ? `${product.stock} available` : 'Out of stock'}</span>
                    </p>
                  )}
                  <div className="product-footer">
                    <span className="product-price">${parseFloat(product.price).toFixed(2)}</span>
                    <button
                      className="btn btn-add-cart"
                      onClick={() => handleAddToCart(product)}
                      disabled={product.stock === 0}
                    >
                      Add to Cart
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;
